pub assume_specification<T: core::marker::PointeeSized>[<*mut T>::addr](
    p: *mut T,
) -> (address: usize)
    ensures
        address == p@.addr,
;

pub assume_specification<T, const N: usize>[<*const [T]>::as_array::<N>](
    p: *const [T],
) -> (result: Option<*const [T; N]>)
    ensures
        result == if p@.metadata == N {
            Some(ptr_from_data::<[T; N]>(PtrData::<[T; N]> {
                addr: p@.addr,
                provenance: p@.provenance,
                metadata: (),
            }))
        } else {
            None
        },
;
